changeSet.sql:
CREATE TABLE organizations (
    id          BIGSERIAL PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT now()
);

CREATE TABLE facilities (
    id              BIGSERIAL PRIMARY KEY,
    organization_id BIGINT NOT NULL REFERENCES organizations(id),
    name            VARCHAR(255) NOT NULL,
    address         VARCHAR(500),
    description     TEXT,
    status          VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    created_at      TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX idx_facilities_org ON facilities(organization_id);

CREATE TABLE engineering_systems (
    id          BIGSERIAL PRIMARY KEY,
    facility_id BIGINT NOT NULL REFERENCES facilities(id) ON DELETE CASCADE,
    name        VARCHAR(255) NOT NULL,
    code        VARCHAR(64),
    description TEXT
);
CREATE INDEX idx_systems_facility ON engineering_systems(facility_id);

CREATE TABLE document_types (
    id   BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    code VARCHAR(64) NOT NULL UNIQUE
);

CREATE TABLE document_pages (
    id          BIGSERIAL PRIMARY KEY,
    document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    page_number INT NOT NULL,
    text        TEXT,
    ocr_used    BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX idx_pages_document ON document_pages(document_id);

CREATE TABLE document_chunks (
    id          BIGSERIAL PRIMARY KEY,
    document_id BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    page_from   INT,
    page_to     INT,
    content     TEXT NOT NULL,
    metadata    TEXT
);
CREATE INDEX idx_chunks_document ON document_chunks(document_id);

CREATE TABLE equipment_sources (
    id           BIGSERIAL PRIMARY KEY,
    equipment_id BIGINT NOT NULL REFERENCES equipment(id) ON DELETE CASCADE,
    document_id  BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    page_number  INT,
    source_text  TEXT
);
CREATE INDEX idx_eq_sources_equipment ON equipment_sources(equipment_id);

CREATE TABLE chats (
    id                    BIGSERIAL PRIMARY KEY,
    user_id               BIGINT NOT NULL REFERENCES users(id),
    facility_id           BIGINT REFERENCES facilities(id) ON DELETE CASCADE,
    engineering_system_id BIGINT REFERENCES engineering_systems(id) ON DELETE SET NULL,
    document_id           BIGINT REFERENCES documents(id) ON DELETE CASCADE,
    title                 VARCHAR(500),
    created_at            TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX idx_chats_user ON chats(user_id);

CREATE TABLE chat_messages (
    id         BIGSERIAL PRIMARY KEY,
    chat_id    BIGINT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,
    role       VARCHAR(16) NOT NULL,
    content    TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX idx_messages_chat ON chat_messages(chat_id);

CREATE TABLE answer_sources (
    id              BIGSERIAL PRIMARY KEY,
    chat_message_id BIGINT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,
    document_id     BIGINT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
    page_number     INT,
    chunk_id        BIGINT REFERENCES document_chunks(id) ON DELETE SET NULL,
    relevance_score REAL
);
CREATE INDEX idx_answer_sources_message ON answer_sources(chat_message_id);
